#include "vmx_ept_hook_transaction.h"
#include <stddef.h>
#include <string.h>
#define R UINT64_C(1)
#define W UINT64_C(2)
#define X UINT64_C(4)
#define MT (UINT64_C(7)<<3)
#define IP (UINT64_C(1)<<6)
#define LP (UINT64_C(1)<<7)
#define A (UINT64_C(1)<<8)
#define D (UINT64_C(1)<<9)
#define SVE (UINT64_C(1)<<63)
#define PA UINT64_C(0x0000FFFFFFFFF000)
#define LEAF_ALLOWED (PA|R|W|X|MT|IP|LP|A|D|SVE)
#define CHILD_FLAGS (R|W|X|MT|IP|A|D|SVE)
static int Span(const void*v,size_t n,uintptr_t*b,uintptr_t*e){uintptr_t f=(uintptr_t)v;if(!v||!n||f>UINTPTR_MAX-n)return 0;*b=f;*e=f+n;return 1;}
static int Separate(const void*l,size_t ln,const void*r,size_t rn){uintptr_t lb,le,rb,re;return Span(l,ln,&lb,&le)&&Span(r,rn,&rb,&re)&&(le<=rb||re<=lb);}
static int Zero(const void*v,size_t n){const unsigned char*p=(const unsigned char*)v;size_t i;if(!v)return 0;for(i=0;i<n;++i)if(p[i])return 0;return 1;}
static int MtValid(uint64_t e){uint64_t t=(e&MT)>>3;return t==0||t==1||t==4||t==5||t==6;}
bool VmxEptHookPlanValid(const VMX_EPT_HOOK_PLAN*p){uint64_t base,original,parent;uint8_t permissions;if(!p||p->Reserved32||p->Reserved8[0]||p->Reserved8[1]||p->Reserved8[2]||(p->GuestPhysicalPage&4095)||!p->PageTablePhysicalAddress||(p->PageTablePhysicalAddress&4095)||p->TargetIndex>=VMX_EPT_HOOK_PTE_COUNT||p->TargetIndex!=(uint32_t)((p->GuestPhysicalPage>>12)&0x1ff)||!p->TrapPermissions||(p->TrapPermissions&~VMX_EPT_HOOK_PERMISSION_MASK)||!(p->OriginalParentEntry&LP)||(p->OriginalParentEntry&~LEAF_ALLOWED)||!MtValid(p->OriginalParentEntry))return false;permissions=(uint8_t)(p->OriginalParentEntry&VMX_EPT_HOOK_PERMISSION_MASK);if(!permissions||(p->TrapPermissions&permissions)!=p->TrapPermissions)return false;base=p->OriginalParentEntry&PA;if((base&(VMX_EPT_HOOK_LARGE_PAGE_BYTES-1))||p->GuestPhysicalPage<base||p->GuestPhysicalPage>=base+VMX_EPT_HOOK_LARGE_PAGE_BYTES)return false;original=p->GuestPhysicalPage|(p->OriginalParentEntry&CHILD_FLAGS);parent=p->PageTablePhysicalAddress|permissions;if(p->OriginalParentEntry&A)parent|=A;return p->OriginalTargetEntry==original&&p->HookedTargetEntry==(original&~(uint64_t)p->TrapPermissions)&&p->ReplacementParentEntry==parent;}
VMX_EPT_HOOK_STATUS VmxEptHookPlan2Mb(uint64_t gpa,uint8_t traps,uint64_t parent,uint64_t pt,uint64_t entries[VMX_EPT_HOOK_PTE_COUNT],VMX_EPT_HOOK_PLAN*out){uint64_t staged[VMX_EPT_HOOK_PTE_COUNT],base,flags;VMX_EPT_HOOK_PLAN p;uint32_t i;if(!entries||!out||!Separate(entries,sizeof(staged),out,sizeof(*out))||(gpa&4095)||!pt||(pt&4095)||!traps||(traps&~VMX_EPT_HOOK_PERMISSION_MASK)||!(parent&LP)||(parent&~LEAF_ALLOWED)||!MtValid(parent)||!(parent&VMX_EPT_HOOK_PERMISSION_MASK)||(traps&parent)!=traps)return VMX_EPT_HOOK_INVALID;base=parent&PA;if((base&(VMX_EPT_HOOK_LARGE_PAGE_BYTES-1))||gpa<base||gpa>=base+VMX_EPT_HOOK_LARGE_PAGE_BYTES)return VMX_EPT_HOOK_UNSUPPORTED;flags=parent&CHILD_FLAGS;for(i=0;i<VMX_EPT_HOOK_PTE_COUNT;++i)staged[i]=base+(uint64_t)i*VMX_EPT_HOOK_PAGE_BYTES|flags;memset(&p,0,sizeof(p));p.GuestPhysicalPage=gpa;p.PageTablePhysicalAddress=pt;p.OriginalParentEntry=parent;p.ReplacementParentEntry=pt|(parent&VMX_EPT_HOOK_PERMISSION_MASK);if(parent&A)p.ReplacementParentEntry|=A;p.TargetIndex=(uint32_t)((gpa>>12)&0x1ff);p.TrapPermissions=traps;p.OriginalTargetEntry=staged[p.TargetIndex];p.HookedTargetEntry=p.OriginalTargetEntry&~(uint64_t)traps;staged[p.TargetIndex]=p.HookedTargetEntry;if(!VmxEptHookPlanValid(&p))return VMX_EPT_HOOK_INVARIANT;memcpy(entries,staged,sizeof(staged));*out=p;return VMX_EPT_HOOK_OK;}
bool VmxEptHookRecordValid(const VMX_EPT_HOOK_RECORD*r){if(!r)return false;if(r->Stage==VMX_EPT_HOOK_STAGE_FREE)return Zero(r,sizeof(*r));return !r->Reserved&&r->Generation&&r->Stage>=VMX_EPT_HOOK_STAGE_PREPARED&&r->Stage<=VMX_EPT_HOOK_STAGE_ROLLBACK_PENDING&&VmxEptHookPlanValid(&r->Plan);}
VMX_EPT_HOOK_STATUS VmxEptHookPrepare(const VMX_EPT_HOOK_PLAN*p,uint64_t generation,VMX_EPT_HOOK_RECORD*r){VMX_EPT_HOOK_RECORD s;if(!p||!r||!Separate(p,sizeof(*p),r,sizeof(*r))||!generation||!VmxEptHookPlanValid(p)||!Zero(r,sizeof(*r)))return VMX_EPT_HOOK_INVALID;memset(&s,0,sizeof(s));s.Stage=VMX_EPT_HOOK_STAGE_PREPARED;s.Generation=generation;s.Plan=*p;*r=s;return VMX_EPT_HOOK_OK;}
VMX_EPT_HOOK_STATUS VmxEptHookCommit(VMX_EPT_HOOK_RECORD*r,uint64_t parent,uint64_t target){if(!VmxEptHookRecordValid(r))return VMX_EPT_HOOK_INVALID;if(r->Stage!=VMX_EPT_HOOK_STAGE_PREPARED)return VMX_EPT_HOOK_BUSY;if(parent!=r->Plan.ReplacementParentEntry||target!=r->Plan.HookedTargetEntry)return VMX_EPT_HOOK_INVARIANT;r->Stage=VMX_EPT_HOOK_STAGE_COMMITTED;return VMX_EPT_HOOK_OK;}
VMX_EPT_HOOK_STATUS VmxEptHookBeginRollback(VMX_EPT_HOOK_RECORD*r,uint64_t generation){if(!VmxEptHookRecordValid(r))return VMX_EPT_HOOK_INVALID;if(r->Stage==VMX_EPT_HOOK_STAGE_ROLLBACK_PENDING)return r->Generation==generation?VMX_EPT_HOOK_OK:VMX_EPT_HOOK_BUSY;if(r->Stage!=VMX_EPT_HOOK_STAGE_COMMITTED)return VMX_EPT_HOOK_BUSY;if(!generation||generation<=r->Generation)return VMX_EPT_HOOK_INVALID;r->Generation=generation;r->Stage=VMX_EPT_HOOK_STAGE_ROLLBACK_PENDING;return VMX_EPT_HOOK_OK;}
VMX_EPT_HOOK_STATUS VmxEptHookCompleteRollback(VMX_EPT_HOOK_RECORD*r,uint64_t parent,uint64_t target){VMX_EPT_HOOK_RECORD z={0};if(!VmxEptHookRecordValid(r))return VMX_EPT_HOOK_INVALID;if(r->Stage!=VMX_EPT_HOOK_STAGE_ROLLBACK_PENDING)return VMX_EPT_HOOK_BUSY;if(parent!=r->Plan.OriginalParentEntry||target!=r->Plan.OriginalTargetEntry)return VMX_EPT_HOOK_INVARIANT;*r=z;return VMX_EPT_HOOK_OK;}
VMX_EPT_HOOK_STATUS VmxEptHookAbortPrepare(VMX_EPT_HOOK_RECORD*r,uint64_t parent){VMX_EPT_HOOK_RECORD z={0};if(!VmxEptHookRecordValid(r))return VMX_EPT_HOOK_INVALID;if(r->Stage!=VMX_EPT_HOOK_STAGE_PREPARED)return VMX_EPT_HOOK_BUSY;if(parent!=r->Plan.OriginalParentEntry)return VMX_EPT_HOOK_INVARIANT;*r=z;return VMX_EPT_HOOK_OK;}
